-- Derived approved-date serving projection; interval authority remains source of truth.
BEGIN;
CREATE TABLE IF NOT EXISTS public.pokemon_market_explorer_card_daily_states (market_date date NOT NULL,card_variant_id uuid NOT NULL,set_id uuid NOT NULL,market_price numeric NOT NULL CHECK(market_price>0),PRIMARY KEY(market_date,card_variant_id));
COMMENT ON TABLE public.pokemon_market_explorer_card_daily_states IS 'Derived approved-date query serving projection; interval authority remains source of truth.';
CREATE INDEX IF NOT EXISTS idx_pokemon_market_explorer_card_daily_states_set_date ON public.pokemon_market_explorer_card_daily_states(set_id,market_date,card_variant_id) INCLUDE(market_price);
ALTER TABLE public.pokemon_market_explorer_card_daily_states ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.pokemon_market_explorer_card_daily_states FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON TABLE public.pokemon_market_explorer_card_daily_states TO service_role;
CREATE TABLE IF NOT EXISTS public.pokemon_market_explorer_card_daily_coverage(set_id uuid PRIMARY KEY,first_market_date date NOT NULL,computed_through date NOT NULL,row_count bigint NOT NULL CHECK(row_count>=0),refreshed_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(first_market_date<=computed_through));
ALTER TABLE public.pokemon_market_explorer_card_daily_coverage ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.pokemon_market_explorer_card_daily_coverage FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON TABLE public.pokemon_market_explorer_card_daily_coverage TO service_role;
CREATE OR REPLACE FUNCTION public.get_pokemon_market_explorer_filtered_cohort_daily_candidate(p_set_ids uuid[], p_start_date date, p_end_date date, p_card_ids uuid[] DEFAULT NULL::uuid[], p_segment_ids text[] DEFAULT NULL::text[], p_pokemon_ids bigint[] DEFAULT NULL::bigint[], p_price_segment_ids text[] DEFAULT NULL::text[], p_release_age_cohort_ids text[] DEFAULT NULL::text[], p_top_n integer DEFAULT NULL::integer)
 RETURNS TABLE(market_date date, constituent_count bigint, eligible_universe_count bigint, basket_value numeric, common_count bigint, common_current_value numeric, common_previous_value numeric, current_constituents jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
 SET work_mem TO '16MB'
 SET enable_nestloop TO 'off'
AS $function$
with coverage_ok as materialized(select count(*)=cardinality(p_set_ids) ok from public.pokemon_market_explorer_card_daily_coverage where set_id=any(p_set_ids) and first_market_date<=p_start_date and computed_through>=p_end_date),dates as materialized(select q.market_date,lag(q.market_date) over(order by q.market_date) previous_market_date,max(q.market_date) over() latest_market_date from public.pokemon_market_date_quality q cross join coverage_ok c where c.ok and q.tcg='pokemon' and q.status in('READY','LEGACY_VERIFIED') and q.market_date between p_start_date and p_end_date),static_variants as materialized(select o.card_variant_id from public.pokemon_card_variant_market_price_intervals o where o.valid_to is null and o.set_id=any(p_set_ids) and (p_card_ids is null or cardinality(p_card_ids)=0 or o.canonical_card_id=any(p_card_ids)) and (p_segment_ids is null or cardinality(p_segment_ids)=0 or public.market_explorer_rarity_segment(o.rarity)=any(p_segment_ids)) and (p_pokemon_ids is null or cardinality(p_pokemon_ids)=0 or exists(select 1 from public.pokemon_card_desirability_links l where l.pokemon_canonical_card_id=o.canonical_card_id and l.pokemon_reference_id=any(p_pokemon_ids)))),panel as materialized(select d.market_date,d.previous_market_date,s.card_variant_id,s.market_price from dates d join public.pokemon_market_explorer_card_daily_states s on s.market_date=d.market_date and s.set_id=any(p_set_ids) join static_variants v on v.card_variant_id=s.card_variant_id join public.sets sr on sr.id=s.set_id where (p_price_segment_ids is null or cardinality(p_price_segment_ids)=0 or ('obtainable'=any(p_price_segment_ids) and s.market_price<10) or ('intermediate'=any(p_price_segment_ids) and s.market_price>=10 and s.market_price<100) or ('premium'=any(p_price_segment_ids) and s.market_price>=100)) and (p_release_age_cohort_ids is null or cardinality(p_release_age_cohort_ids)=0 or (sr.release_date is not null and d.market_date>=sr.release_date and (('new'=any(p_release_age_cohort_ids) and d.market_date-sr.release_date<=180) or ('recent'=any(p_release_age_cohort_ids) and d.market_date-sr.release_date between 181 and 730) or ('established'=any(p_release_age_cohort_ids) and d.market_date-sr.release_date between 731 and 1825) or ('legacy'=any(p_release_age_cohort_ids) and d.market_date-sr.release_date>1825))))),eligible as materialized(select market_date,count(*)::bigint n from panel group by market_date),ranked as materialized(select p.*,row_number() over(partition by market_date order by market_price desc,card_variant_id) market_rank from panel p where p_top_n is not null),selected as materialized(select p.*,null::bigint market_rank from panel p where p_top_n is null union all select r.* from ranked r where r.market_rank<=p_top_n),series as materialized(select cur.market_date,count(*)::bigint constituent_count,e.n::bigint eligible_universe_count,sum(cur.market_price)::numeric basket_value,count(prev.card_variant_id)::bigint common_count,coalesce(sum(cur.market_price) filter(where prev.card_variant_id is not null),0)::numeric common_current_value,coalesce(sum(prev.market_price),0)::numeric common_previous_value from selected cur join eligible e on e.market_date=cur.market_date left join selected prev on prev.market_date=cur.previous_market_date and prev.card_variant_id=cur.card_variant_id group by cur.market_date,e.n),latest as materialized(select s.*,case when s.market_rank is null then row_number() over(order by s.market_price desc,s.card_variant_id) else s.market_rank end final_rank from selected s join dates d on d.market_date=s.market_date and d.market_date=d.latest_market_date),payload as materialized(select coalesce(jsonb_agg(jsonb_build_object('card_variant_id',l.card_variant_id,'canonical_card_id',o.canonical_card_id,'legacy_card_id',o.legacy_card_id,'set_id',o.set_id,'card_name',o.card_name,'card_number',o.card_number,'rarity',o.rarity,'edition',o.edition,'printing_type',o.printing_type,'special_type',o.special_type,'image_url',o.image_url,'market_date',l.market_date,'market_price',l.market_price,'rank',l.final_rank) order by l.final_rank),'[]'::jsonb) body from latest l join public.pokemon_card_variant_market_price_intervals o on o.card_variant_id=l.card_variant_id and o.valid_to is null) select s.market_date,s.constituent_count,s.eligible_universe_count,s.basket_value,s.common_count,s.common_current_value,s.common_previous_value,case when s.market_date=d.latest_market_date then p.body else null end from series s join dates d on d.market_date=s.market_date cross join payload p order by s.market_date $function$
;
REVOKE ALL ON FUNCTION public.get_pokemon_market_explorer_filtered_cohort_daily_candidate(uuid[],date,date,uuid[],text[],bigint[],text[],text[],integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_pokemon_market_explorer_filtered_cohort_daily_candidate(uuid[],date,date,uuid[],text[],bigint[],text[],text[],integer) TO service_role;
COMMIT;

